class Solution:
    def shortestPalindrome(self, s: str) -> str:
        n = len(s)
        if n == 0:
            return s

        i = 0
        j = n - 1
        while j > 0:
            if s[i] == s[j]:
                i += 1
                j -= 1
            else:
                break

        if j == 0:
            return s

        suffix = s[i+1:]
        middle = s[:i+1]

        reversed_suffix = suffix[::-1]
        candidate = reversed_suffix + s

        kmp = [0] * (n + 1)
        pattern = s + "#" + s[::-1]
        m = len(pattern)
        for idx in range(1, m):
            length = kmp[idx - 1]
            while length > 0 and pattern[idx] != pattern[length]:
                length = kmp[length - 1]
            if pattern[idx] == pattern[length]:
                length += 1
            kmp[idx] = length

        longest_palindrome_prefix_len = kmp[-1]
        remaining = s[longest_palindrome_prefix_len:]
        return remaining[::-1] + s
